function makeWeekBoardDay(d){const today=isoDate(new Date()),date=isoDate(d),es=events.filter(e=>e.date===date&&(activeTeam==='ALL'||e.team===activeTeam)).sort((a,b)=>a.start.localeCompare(b.start));const col=document.createElement('div');col.className='week-board-day';col.innerHTML=`<div class="week-board-head ${date===today?'today':''}"><b>${fmtDate(date,{weekday:'long'})}</b><small>${fmtDate(date,{day:'2-digit',month:'2-digit'})} · ${dayWindow(date)[0]}–22:00 ${calendarBadges(date)}</small></div><div class="week-board-events">${es.length?es.map(e=>`<div class="week-board-event" data-id="${esc(e.id)}" style="--team:${teamBy(e.team).c}"><b>${isGame(e.type)&&e.venueType==='heim'?'<span class="home-tag">HEIMSPIEL</span> ':''}${esc(e.matchStart?'Anstoß '+e.matchStart:e.start+'–'+e.end)} · ${esc(derivedTitle(e))}</b><span>${esc(fieldLabel(e.field))}${e.matchStart?' · Block '+esc(e.start)+'–'+esc(e.end):''}${e.trainer?' · '+esc(e.trainer):''}</span></div>`).join(''):'<div class="week-board-empty">frei / keine Termine</div>'}</div>`;col.querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>openEdit(events.find(e=>e.id===x.dataset.id)));return col}
