function renderMonth(){const base=addDays(currentMonday,3),start=new Date(base.getFullYear(),base.getMonth(),1),end=new Date(base.getFullYear(),base.getMonth()+1,0),es=filteredForRange(isoDate(start),isoDate(end)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));$('monthLabel').textContent=new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric'}).format(start);if(!es.length){$('monthList').innerHTML='<div class="hint">In diesem Monat sind noch keine Termine eingetragen.</div>';return}let html='',last='';for(const e of es){if(e.date!==last){html+=`<div class="month-day">${fmtDate(e.date,{weekday:'long',day:'2-digit',month:'long'})}${calendarBadges(e.date)}</div>`;last=e.date}const t=teamBy(e.team),home=isGame(e.type)&&e.venueType==='heim'?'<span class="home-tag">HEIMSPIEL</span> ':'';html+=`<div class="list-item" data-id="${e.id}"><i class="list-stripe" style="--team:${t.c}"></i><div class="list-main"><b>${home}${e.matchStart?'Anstoß '+e.matchStart+' · ':e.start+'–'+e.end+' · '}${derivedTitle(e)}</b><small>${t.name} · ${fieldLabel(e.field)}${e.matchStart?' · Block '+e.start+'–'+e.end:''}${e.cabins==='2'?' · Kabinen Heim+Gast':''}${e.trainer?' · '+e.trainer:''} · ${statusLabel(e.status)}${e.updatedBy?' · zuletzt '+e.updatedBy:''}</small></div><div class="chev">›</div></div>`}$('monthList').innerHTML=html;$('monthList').querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>openEdit(events.find(e=>e.id===x.dataset.id)))}
function durationHours(e){return Math.max(0,(minOf(e.end)-minOf(e.start))/60)}
function overviewItem(e,kind=''){const t=teamBy(e.team),tag=kind==='game'?'Heimspiel':kind==='changed'?'Geändert':kind==='event'?'Info':typeLabel(e.type);const tm=e.matchStart?`Anstoß ${e.matchStart} · Platz/Kabinen ${e.start}–${e.end}`:`${e.start}–${e.end}`;return `<div class="overview-item ${kind}" data-id="${esc(e.id)}" style="--team:${t.c}"><i class="mark"></i><div class="copy"><b>${esc(fmtDate(e.date,{weekday:'short',day:'2-digit',month:'2-digit'}))} · ${esc(tm)} · ${esc(derivedTitle(e))}</b><small>${esc(t.name)}${e.trainer?' · '+esc(e.trainer):''} · ${esc(fieldLabel(e.field))}${e.opponent?' · '+esc(e.opponent):''}${e.cabins==='2'?' · 2 Kabinen Heim+Gast':''}${e.updatedBy?' · geändert von '+esc(e.updatedBy):''}${e.changeReason?' · '+esc(e.changeReason):''}</small></div><span class="tag">${esc(tag)}</span></div>`}
