function exportCSV(){const head=['Datum','Block von','Block bis','Anstoß','Spielende','Mannschaft','Art','Titel','Trainer/Verantwortlich','Platz','Heim/Auswärts','Gegner','Kabinen','Status','Quelle','Geändert von','Änderungsgrund','Notiz'];const rows=events.slice().sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).map(e=>[e.date,e.start,e.end,e.matchStart||'',e.matchEnd||'',teamBy(e.team).name,typeLabel(e.type),e.title||'',e.trainer||'',fieldLabel(e.field),e.venueType||'',e.opponent||'',cabinLabel(e.cabins),statusLabel(e.status),e.source||'',e.updatedBy||'',e.changeReason||'',e.note||'']);const q=v=>'"'+String(v??'').replaceAll('\"','\"\"')+'"';const csv='\ufeff'+[head,...rows].map(r=>r.map(q).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='SVB-Platzplan-'+isoDate(new Date())+'.csv';a.click();URL.revokeObjectURL(a.href)}$('exportCsvBtn').onclick=exportCSV;

