function addMin(t,delta){let m=minOf(t)+delta;m=((m%1440)+1440)%1440;return minutesToTime(m)}
function gameMinutes(team,type,raw=''){if(type==='turnier'||/kinderfestival|kinderfußball|festival/i.test(raw))return 120;return ({H1:90,H2:90,AH:90,A:90,B:80,C:70,D:60,E:50,F:60,G:60})[team]||90}
function bfvTeamFromText(raw){const x=String(raw||'');if(/SV\s+Buckenhofen\s+II\b/i.test(x))return'H2';if(/A-Junioren|U19|\bA-Jun\./i.test(x))return'A';if(/B-Junioren|U17|\bB-Jun\./i.test(x))return'B';if(/C-Junioren|U15|\bC-Jun\./i.test(x))return'C';if(/D-Junioren|U13|\bD-Jun\./i.test(x))return'D';if(/E-Junioren|U11|\bE-Jun\./i.test(x))return'E';if(/F-Junioren|U9|\bF-Jun\./i.test(x))return'F';if(/G-Junioren|U7|\bG-Jun\./i.test(x))return'G';if(/Alte Herren|\bAH\b/i.test(x))return'AH';if(/Herren/i.test(x))return /Buckenhofen\s+II/i.test(x)?'H2':'H1';return settings.defaultTeam||'D'}
function bfvTypeFromText(raw){const x=String(raw||'');if(/pokal|verbands-pokal|toto|\bPO\b/i.test(x))return'pokal';if(/freundschaft|\bFS\b/i.test(x))return'freundschaft';if(/kinderfußball|festival|turnier/i.test(x))return'turnier';return'liga'}
function cleanBfvOpponent(v){return String(v||'').replace(/\s+/g,' ').replace(/^(?:-|–|:)\s*/,'').replace(/\s*(?:Zum Spiel|Zur Gruppe|Sportanlage.*)$/i,'').trim()}
function opponentFromRaw(raw){const x=String(raw||'').replace(/\s+/g,' ').trim();let m=x.match(/SV\s+Buckenhofen(?:\s+II)?(?:\s*-\s*Kinderfestival)?\s*(?:-|–|:|gegen)?\s+(.+?)(?=\s+(?:Zum Spiel|Zur Gruppe|Sportanlage|ME\b|PO\b|FS\b)|$)/i);if(m){const o=cleanBfvOpponent(m[1]);if(o&&!/^SV\s+Buckenhofen/i.test(o))return o}m=x.match(/SV\s+Buckenhofen(?:\s+II)?\s+(.{3,80})$/i);if(m){const o=cleanBfvOpponent(m[1]);if(o&&!/^SV\s+Buckenhofen/i.test(o))return o}return''}
function bfvFieldFromRaw(raw){if($('bfvVenueMap').value!=='auto')return $('bfvDefaultField').value;const x=String(raw||'');if(/Zur Staustufe 8[^\n]*Platz\s*2|Sportanlage Forchheim[^\n]*Platz\s*2/i.test(x))return'B';if(/Zur Staustufe 8[^\n]*Platz\s*1|Sportanlage Forchheim[^\n]*Platz\s*1/i.test(x))return'A';return $('bfvDefaultField').value}
function bfvIsHome(raw){const x=String(raw||'').replace(/\s+/g,' ');if(/Zur Staustufe 8|Sportanlage Forchheim/i.test(x))return true;if(/SV\s+Buckenhofen(?:\s+II)?(?:\s*-\s*Kinderfestival)?\s*(?:-|–|:)/i.test(x))return true;const pos=x.search(/SV\s+Buckenhofen/i);if(pos<0)return false;const before=x.slice(Math.max(0,pos-55),pos),after=x.slice(pos,pos+120);if(/\b(?:ME|PO|FS)\b[^]{0,45}$/i.test(before)&&!/^SV\s+Buckenhofen\s+II/i.test(after))return true;return false}
function parseBfvDate(v){const m=String(v).match(/\b(\d{1,2})\.(\d{1,2})\.(\d{2,4})\b/);if(!m)return'';let y=m[3];if(y.length===2)y='20'+y;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}
async function extractPdfLines(file){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;const out=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),tc=await page.getTextContent(),items=tc.items.filter(i=>String(i.str||'').trim()).map(i=>({s:String(i.str).trim(),x:i.transform[4],y:i.transform[5]})).sort((a,b)=>b.y-a.y||a.x-b.x);const lines=[];for(const it of items){let line=lines.find(l=>Math.abs(l.y-it.y)<2.6);if(!line){line={y:it.y,items:[]};lines.push(line)}line.items.push(it)}lines.sort((a,b)=>b.y-a.y);for(const l of lines){l.items.sort((a,b)=>a.x-b.x);const text=l.items.map(i=>i.s).join(' ').replace(/\s+/g,' ').trim();if(text)out.push(text)}}return out}
function buildBfvRecords(lines){const starts=[];for(let i=0;i<lines.length;i++){if(/\b\d{1,2}\.\d{1,2}\.\d{2,4}\b/.test(lines[i])&&/\b\d{1,2}:\d{2}\b/.test(lines[i]))starts.push(i)}const recs=[];for(let n=0;n<starts.length;n++){const a=starts[n],b=starts[n+1]??Math.min(lines.length,a+10);const chunk=lines.slice(a,Math.min(b,a+10));const raw=chunk.join(' | ');if(!/SV\s+Buckenhofen/i.test(raw))continue;const date=parseBfvDate(raw),tm=(raw.match(/\b([0-2]?\d:[0-5]\d)\b/)||[])[1]||'';if(!date||!tm)continue;recs.push({raw,date,kickoff:tm})}return recs}
function dedupeBfv(recs){const seen=new Set();return recs.filter(r=>{const k=[r.date,r.kickoff,r.raw.replace(/\s+/g,' ').slice(0,160)].join('|');if(seen.has(k))return false;seen.add(k);return true})}
function enrichBfvRecord(r,i){const team=bfvTeamFromText(r.raw),type=bfvTypeFromText(r.raw),duration=gameMinutes(team,type,r.raw),matchEnd=addMin(r.kickoff,duration),field=bfvFieldFromRaw(r.raw),opponent=opponentFromRaw(r.raw)||'Gegner laut BFV';return{...r,id:'bfv-'+i,selected:true,team,type,duration,matchEnd,blockStart:addMin(r.kickoff,-30),blockEnd:addMin(matchEnd,30),field,opponent,sourceKey:`BFV|${r.date}|${r.kickoff}|${team}|${normName(opponent)}`}}
function renderBfvPreview(){const root=$('bfvPreview');if(!bfvCandidates.length){root.innerHTML='<div class="hint">Keine sicheren SVB-Heimspiele erkannt. Falls die PDF anders aufgebaut ist, bitte die originale BFV-PDF schicken – dann passe ich den Parser an.</div>';$('importBfvPdfBtn').classList.add('hidden');return}root.innerHTML=`<div class="bfv-summary">${bfvCandidates.length} Heimspiel${bfvCandidates.length===1?'':'e'} erkannt · alle ausgewählt · 30 Min. Vor-/Nachlauf · 2 Kabinen</div>`+bfvCandidates.map((r,i)=>`<div class="bfv-row" data-bfv-row="${i}" style="--team:${teamBy(r.team).c}"><div class="bfv-row-top"><input type="checkbox" data-bfv-selected="${i}" ${r.selected?'checked':''}><b>${fmtDate(r.date,{weekday:'short',day:'2-digit',month:'2-digit'})} · Anstoß ${esc(r.kickoff)} · ${esc(teamBy(r.team).name)}</b><span class="spacer"></span><span class="home-tag">HEIMSPIEL</span></div><small>${esc(typeLabel(r.type))} · Gegner: <b>${esc(r.opponent)}</b> · <span class="cabin-pair">Kabinen Heim + Gast</span> · Platzblock ${esc(r.blockStart)}–${esc(r.blockEnd)}</small><div class="bfv-row-grid"><select data-bfv-team="${i}">${TEAMS.filter(t=>!['FS','V'].includes(t.id)).map(t=>`<option value="${t.id}" ${t.id===r.team?'selected':''}>${esc(t.name)}</option>`).join('')}</select><select data-bfv-field="${i}"><option value="A" ${r.field==='A'?'selected':''}>A komplett</option><option value="B" ${r.field==='B'?'selected':''}>B komplett</option></select><select data-bfv-duration="${i}">${[40,50,60,70,80,90,120].map(m=>`<option value="${m}" ${m===r.duration?'selected':''}>${m} Min Spiel</option>`).join('')}</select></div><div class="bfv-row-grid" style="grid-template-columns:1fr"><input data-bfv-opponent="${i}" value="${esc(r.opponent)}" aria-label="Gegner"></div><div class="bfv-raw">BFV: ${esc(r.raw)}</div></div>`).join('');root.querySelectorAll('[data-bfv-selected]').forEach(x=>x.onchange=()=>{bfvCandidates[Number(x.dataset.bfvSelected)].selected=x.checked;x.closest('.bfv-row').classList.toggle('bfv-skip',!x.checked)});root.querySelectorAll('[data-bfv-team]').forEach(x=>x.onchange=()=>{const r=bfvCandidates[Number(x.dataset.bfvTeam)];r.team=x.value;r.duration=gameMinutes(r.team,r.type,r.raw);r.matchEnd=addMin(r.kickoff,r.duration);r.blockStart=addMin(r.kickoff,-30);r.blockEnd=addMin(r.matchEnd,30);r.sourceKey=`BFV|${r.date}|${r.kickoff}|${r.team}|${normName(r.opponent)}`;renderBfvPreview()});root.querySelectorAll('[data-bfv-field]').forEach(x=>x.onchange=()=>bfvCandidates[Number(x.dataset.bfvField)].field=x.value);root.querySelectorAll('[data-bfv-duration]').forEach(x=>x.onchange=()=>{const r=bfvCandidates[Number(x.dataset.bfvDuration)];r.duration=Number(x.value);r.matchEnd=addMin(r.kickoff,r.duration);r.blockEnd=addMin(r.matchEnd,30);renderBfvPreview()});root.querySelectorAll('[data-bfv-opponent]').forEach(x=>x.onchange=()=>{const r=bfvCandidates[Number(x.dataset.bfvOpponent)];r.opponent=x.value.trim()||'Gegner laut BFV';r.sourceKey=`BFV|${r.date}|${r.kickoff}|${r.team}|${normName(r.opponent)}`});$('importBfvPdfBtn').classList.remove('hidden')}
if($('analyzeBfvPdfBtn'))$('analyzeBfvPdfBtn').onclick=async()=>{const file=$('bfvPdfFile').files[0];if(!file)return alert('Bitte zuerst die BFV-Vereinsspielplan-PDF auswählen.');$('bfvPreview').innerHTML='<div class="bfv-summary">BFV-PDF wird gelesen …</div>';$('importBfvPdfBtn').classList.add('hidden');try{const lines=await extractPdfLines(file),records=dedupeBfv(buildBfvRecords(lines)).filter(r=>bfvIsHome(r.raw));bfvCandidates=records.map(enrichBfvRecord);renderBfvPreview()}catch(err){console.error(err);$('bfvPreview').innerHTML='<div class="hint">PDF konnte nicht ausgewertet werden: '+esc(err.message)+'</div>'}}
if($('importBfvPdfBtn'))$('importBfvPdfBtn').onclick=async()=>{const selected=bfvCandidates.filter(r=>r.selected);if(!selected.length)return alert('Kein Heimspiel ausgewählt.');let imported=0,skipped=0;for(const r of selected){const duplicate=events.some(e=>e.sourceKey===r.sourceKey||(e.date===r.date&&e.team===r.team&&e.venueType==='heim'&&e.matchStart===r.kickoff&&normName(e.opponent)===normName(r.opponent)));if(duplicate){skipped++;continue}await saveOne({type:r.type,team:r.team,title:'',date:r.date,start:r.blockStart,end:r.blockEnd,matchStart:r.kickoff,matchEnd:r.matchEnd,bufferBefore:30,bufferAfter:30,field:r.field,opponent:r.opponent,trainer:defaultTrainerForTeam(r.team)||settings.name||'SVB',cabins:'2',cabinHome:true,cabinGuest:true,note:`BFV-Heimspiel · Anstoß ${r.kickoff} · Platz und Kabinen 30 Min vorher/nachher reserviert`,changeReason:'BFV-Vereinsspielplan PDF-Import',status:'fix',venueType:'heim',source:'BFV Vereinsspielplan PDF',sourceKey:r.sourceKey,updatedBy:settings.name||'BFV-Import'});imported++}alert(`${imported} Heimspiele importiert.${skipped?` ${skipped} bereits vorhandene Spiele übersprungen.`:''}`);$('bfvPreview').innerHTML=`<div class="bfv-summary">${imported} Heimspiele importiert${skipped?' · '+skipped+' Duplikate übersprungen':''}.</div>`;$('importBfvPdfBtn').classList.add('hidden')}

async function importICS(){const file=$('icsFile').files[0];if(!file)return alert('Bitte zuerst eine .ics-Datei wählen.');const txt=await file.text(),blocks=txt.split('BEGIN:VEVENT').slice(1).map(x=>x.split('END:VEVENT')[0]);let imported=0;for(const b of blocks){const lines=b.split(/\r?\n/),get=key=>{const line=lines.find(l=>l.startsWith(key));return line?line.split(':').slice(1).join(':').trim():''},ds=get('DTSTART'),de=get('DTEND'),sum=get('SUMMARY')||'BFV-Spiel',loc=get('LOCATION');if(!ds)continue;const parse=s=>{const z=s.replace(/[^0-9T]/g,''),date=z.slice(0,8),time=z.includes('T')?z.slice(9,13):'1200';return{date:`${date.slice(0,4)}-${date.slice(4,6)}-${date.slice(6,8)}`,time:`${time.slice(0,2)}:${time.slice(2,4)}`}};const a=parse(ds),z=de?parse(de):{time:minutesToTime(minOf(a.time)+120)},home=/SV Buckenhofen/i.test(sum)&&!new RegExp('[-–]\\s*SV Buckenhofen','i').test(sum);await saveOne({type:'liga',team:$('icsTeam').value,title:sum,date:a.date,start:a.time,end:z.time,field:home?$('icsField').value:'none',opponent:'',trainer:defaultTrainerForTeam($('icsTeam').value)||settings.name||'SVB',cabins:home?'unklar':'keine',note:`Importiert aus BFV / ICS${loc?' · '+loc:''}`,changeReason:'BFV / ICS-Import',status:'fix',venueType:home?'heim':'auswaerts',updatedBy:settings.name||'BFV-Import'});imported++}alert(`${imported} Termine importiert.`)}$('importIcsBtn').onclick=importICS;
function parseCsvLine(line,sep=';'){const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===sep&&!q){out.push(cur);cur=''}else cur+=c}out.push(cur);return out}
async function importCSV(fileArg=null,label='CSV'){
  const file=fileArg||$('csvFile').files[0];if(!file)return alert('Bitte CSV-Datei auswählen.');
  const text=(await file.text()).replace(/^\uFEFF/,'');const lines=text.split(/\r?\n/).filter(Boolean);if(lines.length<2)return alert('CSV enthält keine Daten.');
  const sep=lines[0].includes(';')?';':',';const head=parseCsvLine(lines[0],sep).map(x=>x.trim());const idx=n=>head.findIndex(h=>h.toLocaleLowerCase('de-DE')===n.toLocaleLowerCase('de-DE'));
  let count=0,skipped=0;
  for(const line of lines.slice(1)){
    const r=parseCsvLine(line,sep),get=n=>{const i=idx(n);return i>=0?(r[i]||'').trim():''},getAny=(...ns)=>ns.map(get).find(Boolean)||'';
    const teamName=get('Mannschaft'),typeName=get('Art'),fieldName=get('Platz');
    const team=TEAMS.find(t=>[t.name,t.id,t.short].some(v=>normName(v)===normName(teamName)))?.id||settings.defaultTeam;
    const type=TYPES.find(t=>normName(t[1])===normName(typeName)||normName(t[0])===normName(typeName))?.[0]||'training';
    const field=FIELDS.find(f=>normName(f[1])===normName(fieldName)||normName(f[0])===normName(fieldName))?.[0]||'none';
    const date=get('Datum');if(!date)continue;
    const matchStart=getAny('Anstoß','Anstoss'),matchEnd=get('Spielende'),venueType=get('Heim/Auswärts')||'heim',opponent=get('Gegner');
    const start=getAny('Block von','Von')||(matchStart?addMin(matchStart,-30):'17:00'),end=getAny('Block bis','Bis')||(matchEnd?addMin(matchEnd,30):'18:30');
    const cabinsRaw=get('Kabinen'),cabins=/2|heim.*gast/i.test(cabinsRaw)?'2':(/keine/i.test(cabinsRaw)?'keine':(cabinsRaw||'unklar'));
    const statusRaw=get('Status'),status=({fix:'fix',verschoben:'verschoben',vorläufig:'vorlaeufig',vorlaeufig:'vorlaeufig',abgesagt:'abgesagt'})[normName(statusRaw)]||'fix';
    const source=get('Quelle')||label,sourceKey=matchStart?`${source}|${date}|${matchStart}|${team}|${normName(opponent)}`:'';
    if(sourceKey&&events.some(e=>e.sourceKey===sourceKey||(e.date===date&&e.team===team&&e.matchStart===matchStart&&normName(e.opponent)===normName(opponent)))){skipped++;continue}
    await saveOne({date,start,end,matchStart:matchStart||'',matchEnd:matchEnd||'',bufferBefore:matchStart?30:0,bufferAfter:matchEnd?30:0,team,type,title:get('Titel'),trainer:get('Trainer/Verantwortlich')||(type==='training'?defaultTrainerForTeam(team):''),field,venueType,opponent,cabins,cabinHome:cabins==='2',cabinGuest:cabins==='2',status,source,sourceKey,changeReason:get('Änderungsgrund')||`${label}-Import`,note:get('Notiz'),updatedBy:settings.name||'Admin'});count++
  }
  alert(`${count} ${label}-Termine importiert.${skipped?` ${skipped} Duplikate übersprungen.`:''}`)
}
$('importCsvBtn').onclick=()=>importCSV();
$('importBfvPreparedBtn').onclick=()=>{const f=$('bfvPreparedFile').files[0];if(!f)return alert('Bitte vorbereitete BFV-CSV auswählen.');return importCSV(f,'BFV')};
$('cleanupBfvPdfBtn').onclick=async()=>{const bad=events.filter(e=>e.source==='BFV Vereinsspielplan PDF'||String(e.changeReason||'').includes('BFV-Vereinsspielplan PDF-Import'));if(!bad.length)return alert('Keine alten BFV-PDF-Importe gefunden.');if(!confirm(`${bad.length} alte BFV-PDF-Importe wirklich löschen? Manuell angelegte Termine bleiben erhalten.`))return;for(const e of bad)await deleteDoc(doc(db,'events',e.id));alert(`${bad.length} alte BFV-PDF-Importe gelöscht.`)};
$('loginBtn').onclick=async()=>{const name=$('loginName').value.trim(),pin=$('loginPin').value.trim(),u=accessUser(name);if(!u)return alert('Bitte zuerst deinen Namen auswählen.');if(!/^\d{4}$/.test(pin))return alert('Bitte 4-stellige PIN eingeben.');if(!u.pinHash){const firstAllowed=u.role==='admin'&&!(appConfig.accessUsers||[]).some(x=>x.pinHash);if(!firstAllowed)return alert('Für diesen Zugang wurde noch keine PIN gesetzt. Bitte den Admin fragen.');if(pin!==$('loginPin2').value.trim())return alert('Die PINs stimmen nicht überein.');u.pinHash=await hashPin(u.name,pin);await persistConfig()}const h=await hashPin(u.name,pin);if(h!==u.pinHash)return alert('PIN ist nicht korrekt.');settings.name=u.name;localStorage.setItem('svb_session_name',u.name);localStorage.setItem('svb_session_sig',u.pinHash);if((u.teams||[]).length&&!u.teams.includes(settings.defaultTeam))settings.defaultTeam=u.teams[0];$('loginDialog').close();applyRoleUI();renderAll()};
async function connect(){try{app=initializeApp(firebaseConfig);auth=getAuth(app);db=getFirestore(app);await signInAnonymously(auth);onAuthStateChanged(auth,u=>{if(!u)return;$('syncStatus').textContent='Live synchronisiert · Änderungen sind sofort für alle Trainer sichtbar';$('syncStatus').className='sync online';const q=query(collection(db,'events'),orderBy('date','asc'));if(unsubscribe)unsubscribe();unsubscribe=onSnapshot(q,s=>{const all=s.docs.map(d=>({id:d.id,...d.data()}));const cfg=all.find(d=>d.isConfig||d.id==='_svb_config');if(cfg){appConfig=normalizeConfig(cfg)}else{appConfig=normalizeConfig(DEFAULT_CONFIG)}TEAMS=appConfig.teams||TEAMS;seed();if(sessionValid())applyRoleUI();else showLogin();events=all.filter(d=>!d.isConfig&&d.id!=='_svb_config');renderAll()},err=>{$('syncStatus').textContent='Firestore-Regeln prüfen';$('syncStatus').className='sync';console.error(err)})})}catch(err){$('syncStatus').textContent='Firebase nicht bereit';console.error(err)}}
seed();renderAll();connect();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
